// iso numeric -> territory name, for painting an atlas feature from a rollup.
export const TERRITORY_BY_ISO = Object.fromEntries(
  Object.entries(ISO_BY_TERRITORY).map(([name, iso]) => [iso, name])
);

export const isMicro = (name) => Object.hasOwn(MICRO_CENTROIDS, name);
